            if selected == module:
                raise kind("PRIVATE_BACKEND_TEXT", name=name)
            return original(selected, *args, **kwargs)
    
        monkeypatch.setattr(builtins, "__import__", fail)
        with pytest.raises(RuntimeError) as captured:
            model._backend()
